CREATE TABLE public.pulse_bot_configs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, config jsonb NOT NULL, enabled boolean NOT NULL DEFAULT false, kill_switch boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CHECK (config->>'strategyId' IN ('orb','vwap_reclaim','ema_pullback','ttm_squeeze','rsi2','macd_cross','band_bounce','supertrend','donchian')));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.pulse_bot_configs TO authenticated; GRANT ALL ON public.pulse_bot_configs TO service_role;
ALTER TABLE public.pulse_bot_configs ENABLE ROW LEVEL SECURITY;
CREATE POLICY pulse_configs_owner ON public.pulse_bot_configs FOR ALL TO authenticated USING (user_id=auth.uid()) WITH CHECK (user_id=auth.uid());
CREATE TABLE public.pulse_bot_states (bot_id uuid PRIMARY KEY REFERENCES public.pulse_bot_configs(id), user_id uuid NOT NULL, state jsonb NOT NULL DEFAULT '{}'::jsonb, updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.pulse_bot_states TO authenticated; GRANT ALL ON public.pulse_bot_states TO service_role;
ALTER TABLE public.pulse_bot_states ENABLE ROW LEVEL SECURITY;
CREATE POLICY pulse_states_owner ON public.pulse_bot_states FOR SELECT TO authenticated USING (user_id=auth.uid());
CREATE TABLE public.pulse_bot_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), bot_id uuid NOT NULL REFERENCES public.pulse_bot_configs(id), user_id uuid NOT NULL, kind text NOT NULL, detail jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.pulse_bot_events TO authenticated; GRANT ALL ON public.pulse_bot_events TO service_role;
ALTER TABLE public.pulse_bot_events ENABLE ROW LEVEL SECURITY;
CREATE POLICY pulse_events_owner ON public.pulse_bot_events FOR SELECT TO authenticated USING (user_id=auth.uid());
CREATE INDEX pulse_events_owner_time ON public.pulse_bot_events(user_id,created_at DESC);
CREATE TABLE public.pulse_bot_leases (user_id uuid PRIMARY KEY, token uuid, lease_until timestamptz);
GRANT ALL ON public.pulse_bot_leases TO service_role;
ALTER TABLE public.pulse_bot_leases ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.pulse_acquire_lease(p_user_id uuid,p_token uuid) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ BEGIN INSERT INTO public.pulse_bot_leases(user_id,token,lease_until) VALUES(p_user_id,p_token,now()+interval '50 seconds') ON CONFLICT(user_id) DO UPDATE SET token=EXCLUDED.token,lease_until=EXCLUDED.lease_until WHERE public.pulse_bot_leases.lease_until IS NULL OR public.pulse_bot_leases.lease_until<now(); RETURN FOUND; END; $$;
REVOKE ALL ON FUNCTION public.pulse_acquire_lease(uuid,uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.pulse_acquire_lease(uuid,uuid) TO service_role;
CREATE FUNCTION public.pulse_checkpoint(p_user_id uuid,p_token uuid,p_bot_id uuid,p_state jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ BEGIN PERFORM 1 FROM public.pulse_bot_leases WHERE user_id=p_user_id AND token=p_token AND lease_until>now() FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Bot lease expired'; END IF; IF NOT EXISTS(SELECT 1 FROM public.pulse_bot_configs WHERE id=p_bot_id AND user_id=p_user_id) THEN RAISE EXCEPTION 'Bot owner mismatch'; END IF; INSERT INTO public.pulse_bot_states(bot_id,user_id,state,updated_at) VALUES(p_bot_id,p_user_id,p_state,now()) ON CONFLICT(bot_id) DO UPDATE SET state=EXCLUDED.state,updated_at=now(); END; $$;
REVOKE ALL ON FUNCTION public.pulse_checkpoint(uuid,uuid,uuid,jsonb) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.pulse_checkpoint(uuid,uuid,uuid,jsonb) TO service_role;
CREATE FUNCTION public.pulse_guard_config() RETURNS trigger LANGUAGE plpgsql SET search_path='' AS $$ BEGIN IF auth.role() IS DISTINCT FROM 'authenticated' THEN RETURN NEW; END IF; IF TG_OP='DELETE' THEN IF EXISTS(SELECT 1 FROM public.pulse_bot_states WHERE bot_id=OLD.id AND (state->'position' IS NOT NULL AND state->'position'<>'null'::jsonb OR state->'pending' IS NOT NULL AND state->'pending'<>'null'::jsonb)) THEN RAISE EXCEPTION 'Stop and flatten the bot before deleting it'; END IF; RETURN OLD; END IF; IF NEW.config->>'strategyId'='window20' THEN RAISE EXCEPTION 'Existing IWM bot is managed separately'; END IF; IF TG_OP='UPDATE' AND NEW.user_id IS DISTINCT FROM OLD.user_id THEN RAISE EXCEPTION 'Owner cannot change'; END IF; IF TG_OP='INSERT' OR (TG_OP='UPDATE' AND (NEW.config IS DISTINCT FROM OLD.config OR OLD.kill_switch AND NOT NEW.kill_switch OR NOT OLD.enabled AND NEW.enabled)) THEN IF NOT public.has_recent_password_auth() THEN RAISE EXCEPTION 'Confirm your password before configuring or enabling a bot' USING ERRCODE='42501'; END IF; END IF; IF TG_OP='UPDATE' AND NEW.config IS DISTINCT FROM OLD.config AND EXISTS(SELECT 1 FROM public.pulse_bot_states WHERE bot_id=OLD.id AND (state->'position' IS NOT NULL AND state->'position'<>'null'::jsonb OR state->'pending' IS NOT NULL AND state->'pending'<>'null'::jsonb)) THEN RAISE EXCEPTION 'Stop and flatten the bot before changing its settings'; END IF; NEW.updated_at=now(); RETURN NEW; END; $$;
CREATE TRIGGER pulse_config_security BEFORE INSERT OR UPDATE OR DELETE ON public.pulse_bot_configs FOR EACH ROW EXECUTE FUNCTION public.pulse_guard_config();
ALTER PUBLICATION supabase_realtime ADD TABLE public.pulse_bot_configs,public.pulse_bot_states,public.pulse_bot_events;